const deadline = 1792763341237;
const killed = new Set();
const hp = () => sdk.getState().player.hp;
const food = () => sdk.getInventory().find(i => /shrimp|bread/i.test(i.name));
while (Date.now() < deadline - 180000) {
  if (hp() <= 6) { const f = food(); if (f) await bot.eatFood(f.name); }
  const npcs = sdk.getState().npcs.filter(n => n.attackable && n.reachable && n.level >= 0);
  const target = npcs.find(n => !killed.has(n.name));
  if (!target) break;
  const r = await bot.attack(target);
  if (!r.success) { continue; }
  // wait for kill
  const t0 = Date.now();
  while (Date.now() - t0 < 25000) {
    await sdk.waitForTicks(3);
    const me = sdk.getState().player;
    if (me.hp <= 6) { const f = food(); if (f) await bot.eatFood(f.name); }
    const still = sdk.getState().npcs.find(n => n.index === target.index);
    if (!still || still.hp <= 0) break;
  }
  killed.add(target.name);
}
return { killed: [...killed], hp: hp() };

